(function () {
  'use strict';
  const C=window.LANGKAH_CONTENT, K=window.LangkahCore;
  const lessons=new Map(C.lessons.map(l=>[l.id,l]));
  const main=document.getElementById('main');
  let state=K.initialState(), storageOK=true, toastTimer, quiz=null, lastResult=null, wordSession=null, missionFeedback=null, pendingBukat=null;
  let voices=[], filters={search:'',stage:'all',status:'all'}, wordFilters={search:'',group:'all'};
  const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',path:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M8 5h8a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h8"/>',review:'<path d="M3 9a9 9 0 1 1 0 6M3 3v6h6M12 7v5l3 2"/>',words:'<path d="M3 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3zM13 7a3 3 0 0 1 3-3h5v14h-5a3 3 0 0 0-3 3"/>',missions:'<path d="M4 3h16v13H9l-5 5zM8 7h8M8 11h5"/>',progress:'<path d="M4 20V10M12 20V4M20 20v-7"/>',audio:'<path d="M4 9v6h4l5 4V5L8 9zM17 8a7 7 0 0 1 0 8M20 5a11 11 0 0 1 0 14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',flame:'<path d="M12 2c4 6 8 9 8 14a8 8 0 0 1-16 0c0-3 1-6 4-9 0 4 2 4 2 4s2-4 2-9z"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
  const navItems=[['home','Belajar'],['path','Daftar pelajaran'],['review','Ulangi'],['words','Kosakata'],['missions','Percakapan'],['progress','Hasil belajar']];
  function icon(name){return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.spark)+'</svg>';}
  function esc(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function pct(num,total){return total?Math.round(num/total*100):0;}
  function notice(text){const el=document.getElementById('storage-notice');el.textContent=text;el.hidden=false;}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5500);}
  function save(){try{localStorage.setItem(K.KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;notice('Browser tidak mengizinkan penyimpanan. Hasil belajar hanya bertahan selama tab ini terbuka. Unduh cadangan di Hasil belajar sebelum menutup tab.');} updateStats();}
  try {const saved=localStorage.getItem(K.KEY);if(saved)state=K.validated(JSON.parse(saved),C);} catch(e){notice('Hasil belajar tersimpan tidak dapat dibaca. Sesi ini dimulai dari awal; file cadangan bisa dibuka kembali melalui Hasil belajar.');storageOK=false;}
  function go(path){if(window.LANGKAH_MODULE_CONTEXT?.navigate){window.LANGKAH_MODULE_CONTEXT.navigate(path);return;}if(location.hash==='#'+path)render();else location.hash=path;}
  function heading(kicker,title,desc,extra=''){return '<div class="page-heading"><div><div class="eyebrow">'+esc(kicker)+'</div><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>'+extra+'</div>';}
  function button(text,route,cls=''){return '<a class="btn '+cls+'" href="#'+esc(route)+'">'+text+'</a>';}
  function audio(text){return '<button class="audio-button" data-action="speak" data-text="'+esc(text)+'" aria-label="Dengarkan: '+esc(text)+'">'+icon('audio')+'</button>';}
  function badge(text,cls=''){return '<span class="badge '+cls+'">'+esc(text)+'</span>';}
  function progress(value,label){return '<div class="progress-track" role="progressbar" aria-label="'+esc(label)+'" aria-valuenow="'+value+'" aria-valuemin="0" aria-valuemax="100"><span style="width:'+value+'%"></span></div>';}
  function nextLesson(){if(state.active)return lessons.get(state.active.lesson);for(const path of C.paths)for(const id of path.lessons)if(!state.completed[id])return lessons.get(id);return lessons.get('f01');}
  function status(id){if(!state.completed[id])return 'Belum dicoba';if((state.reviews[id]?.box||0)>=3)return 'Ingat saat mengulang';return 'Sudah berlatih';}
  function updateStats(){document.getElementById('topbar-stats').innerHTML='<span class="stat-dot" title="Hari belajar berturut-turut">'+icon('flame')+K.streak(state)+' hari</span><span class="stat-dot" title="Poin dari latihan, bukan ukuran kelancaran berbahasa">'+icon('spark')+K.xp(state)+' poin</span>';}
  function updateNav(route){const section=route==='lesson'||route==='practice'||route==='done'?'path':route==='word-flash'?'words':route==='mission'||route==='checks'||route==='check'||route==='diagnostic'||route==='listen'||route==='listen-session'?'missions':route==='review-session'?'review':route;
    const html=items=>items.map(([id,label])=>'<a class="nav-link '+(section===id?'active':'')+'" '+(section===id?'aria-current="page"':'')+' href="#'+id+'">'+icon(id)+'<span>'+esc(label)+'</span></a>').join('');
    document.getElementById('desktop-nav').innerHTML=html(navItems);
    document.getElementById('mobile-nav').innerHTML=html(navItems.filter(x=>x[0]!=='words').map(([id,label])=>[id,id==='path'?'Peta':label]));
  }
  function viewHome(){const l=nextLesson(), path=C.paths[l.stage], count=Object.keys(state.completed).length, daily=K.daily(state), goal=state.settings.goal, due=K.due(state).length;
    return heading('BELAJAR BAHASA INGGRIS','Pelan-pelan, kamu bisa.','Mulai dari sini. Lima latihan pendek untuk satu langkah baru.')+
      '<div class="home-top"><section class="card next-card"><div class="card-topline">'+badge(state.active?'LANJUTKAN SESIMU':count?'LANGKAH BERIKUTNYA':'MULAI DARI TITIK NOL')+'<span class="small muted">± 5–8 menit</span></div><h2>'+esc(l.title)+'</h2><p>'+esc(l.rule.split('. ')[0])+'.</p><div class="meta-line"><span>'+esc(path.title)+'</span><span>5 latihan + coba ucapkan</span></div><div class="button-row">'+button(state.active?'Lanjutkan latihan '+icon('arrow'):'Mulai belajar '+icon('arrow'),state.active?'practice/'+l.id:'lesson/'+l.id)+button('Cek titik awal','diagnostic','secondary')+'</div></section>'+ 
      '<section class="card daily-card"><div class="eyebrow">TARGET HARI INI</div><h3>Sedikit saja sudah bagus.</h3><div class="big-number">'+Math.min(daily,goal)+'<span> / '+goal+'</span></div>'+progress(Math.min(100,pct(daily,goal)),'Target jumlah latihan hari ini')+'<p>'+(daily>=goal?'Target hari ini tercapai. Istirahat juga bagian dari belajar.':'Selesaikan '+Math.max(0,goal-daily)+' latihan lagi. Tidak ada hukuman jika terlewat.')+'</p></section></div>'+
      '<div class="section-row"><h2>Latihan yang pas untukmu</h2><span class="small muted">Tanpa buru-buru.</span></div><div class="quick-grid">'+
      '<a class="card quick-card" href="#review">'+icon('review')+'<h3>'+(due?due+' topik menunggu diulang':'Jaga yang sudah dipelajari')+'</h3><p>'+(due?'Jawab lagi tanpa melihat catatan.':'Materi akan muncul lagi sesuai jadwalmu.')+'</p><span class="tiny-arrow">Buka pengulangan →</span></a>'+
      '<a class="card quick-card" href="#words">'+icon('words')+'<h3>Kata kecil, banyak gunanya</h3><p>161 kata dasar, arti Indonesia, dan kartu latihan mengingat arti.</p><span class="tiny-arrow">Buka kosakata →</span></a>'+
      '<a class="card quick-card" href="#missions">'+icon('missions')+'<h3>Pakai dalam kehidupan nyata</h3><p>Berkenalan, pesan minuman, sampai bertanya arah.</p><span class="tiny-arrow">Coba percakapan →</span></a></div>'+
      '<div class="section-row"><h2>Jalur belajarmu</h2><a class="text-link" href="#path">Lihat semua '+icon('arrow')+'</a></div><a class="card path-strip" href="#path"><div class="step-number">'+String(l.stage).padStart(2,'0')+'</div><div><h3>'+esc(path.title)+'</h3><p>'+esc(path.description)+'</p></div><span class="tiny-progress">'+count+' / 123 pelajaran selesai</span></a><p class="encourage">'+(count?'Kamu sudah menyelesaikan '+count+' langkah. Jawaban yang keliru membantu memilih apa yang perlu diulang.':'Belum tahu satu kata pun? Tidak apa-apa. Delapan pelajaran awal dirancang untuk memulai dari nol.')+'</p>';
  }
  function filteredLessons(){return C.lessons.filter(l=>{const text=(l.title+' '+l.rule+' '+(l.unit||'dasar')).toLowerCase();return text.includes(filters.search.toLowerCase())&&(filters.stage==='all'||String(l.stage)===filters.stage)&&(filters.status==='all'||(filters.status==='new'?!state.completed[l.id]:!!state.completed[l.id]));});}
  function lessonRow(l){return '<a class="lesson-row" href="#lesson/'+l.id+'"><span class="lesson-num">'+(l.unit?'U'+l.unit:'D'+Number(l.id.slice(1)))+'</span><div><strong>'+esc(l.title)+'</strong><small>'+esc(l.pattern)+'</small></div>'+badge(status(l.id),state.completed[l.id]?'':'neutral')+'<span aria-hidden="true">→</span></a>';}
  function pathResults(){const found=filteredLessons();let html='<p class="filter-result">'+found.length+' pelajaran • Semua bisa dibuka. Urutan ini adalah rekomendasi.</p>';
    if(!found.length)return html+'<div class="empty"><h2>Belum ketemu.</h2><p>Coba kata seperti “masa lalu”, “bertanya”, atau “kepemilikan”.</p><button class="btn secondary" data-action="clear-filter">Hapus filter</button></div>';
    for(const p of C.paths){const subset=p.lessons.map(id=>lessons.get(id)).filter(l=>found.includes(l));if(!subset.length)continue;const done=p.lessons.filter(id=>state.completed[id]).length;html+='<details class="card stage" '+(filters.search||filters.stage!=='all'||p.id===C.paths[nextLesson().stage].id?'open':'')+'><summary><span class="step-number">'+p.id.slice(1).padStart(2,'0')+'</span><div><h2>'+esc(p.title)+'</h2><p>'+esc(p.description)+'</p></div>'+badge(done+' / '+p.lessons.length)+'</summary><div class="lesson-list">'+subset.map(lessonRow).join('')+'</div></details>';}
    return html;
  }
  function viewPath(){return heading('DAFTAR PELAJARAN','Langkah kecil, jalur jelas.','Mulai dari dasar atau pilih topik yang ingin kamu pelajari.')+'<div class="filter-bar"><label class="search-wrap">'+icon('search')+'<input type="search" id="lesson-search" placeholder="Cari topik atau nomor unit…" aria-label="Cari pelajaran" value="'+esc(filters.search)+'"></label><select id="stage-filter" aria-label="Pilih tahap"><option value="all">Semua tahap</option>'+C.paths.map((p,i)=>'<option value="'+i+'" '+(filters.stage===String(i)?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select><select id="status-filter" aria-label="Pilih hasil latihan"><option value="all">Semua hasil latihan</option><option value="new" '+(filters.status==='new'?'selected':'')+'>Belum dicoba</option><option value="done" '+(filters.status==='done'?'selected':'')+'>Sudah berlatih</option></select></div><div id="path-results">'+pathResults()+'</div>';}
  function glossary(){return '<details class="glossary"><summary>Bingung dengan istilahnya? Lihat arti dan contoh.</summary><ul><li><strong>Subjek</strong>: siapa atau apa yang dibicarakan. Dalam She is ready, subjeknya She.</li><li><strong>Kata kerja (verb)</strong>: kata seperti eat (makan) atau go (pergi).</li><li><strong>Bentuk dasar, kedua, dan ketiga</strong>: misalnya go, went, gone. Went dipakai untuk masa lalu. Gone dipakai setelah have/has. Pada kata lain, bentuk ketiga juga dipakai dalam kalimat pasif, seperti is cleaned.</li><li><strong>Tunggal dan jamak</strong>: satu dan lebih dari satu. A book = satu buku; two books = dua buku.</li><li><strong>Objek</strong>: yang menerima tindakan. Dalam I read a book, objeknya a book.</li><li><strong>Pelengkap</strong>: keterangan setelah kata seperti am/is/are. Dalam I am happy, happy menjelaskan keadaan saya.</li><li><strong>Klausa</strong>: bagian kalimat yang punya subjek dan kata kerja. Contohnya, I was tired dalam I stayed home because I was tired.</li><li><strong>Bentuk singkat (kontraksi)</strong>: dua kata yang digabung, seperti I am menjadi I’m.</li><li><strong>Kata depan</strong>: kata seperti in, on, at, atau to untuk hubungan tempat, waktu, dan lainnya.</li><li><strong>Kata bantu</strong>: kata seperti do, have, atau be yang membantu membentuk pertanyaan dan pola lainnya. Modal adalah kata seperti can, must, atau will.</li></ul><a class="text-link" href="#reference">Lihat contoh pola dan bentuk kata kerja</a></details>';}
  function viewLesson(id){const l=lessons.get(id);if(!l)return viewNotFound();const previous=state.completed[id];const resume=state.active?.lesson===id;
    return heading(l.unit?'UNIT '+l.unit+' · '+C.paths[l.stage].title:'DASAR '+Number(id.slice(1))+' · TITIK NOL',l.title,'Pahami satu pola. Coba lima latihan. Pakai dalam satu kalimat.')+
      '<div class="lesson-layout"><div class="lesson-body"><section class="card"><h2>Pahami dulu</h2><p class="rule-copy">'+esc(l.rule)+'</p><div class="pattern">'+esc(l.pattern)+'</div><div class="tip"><strong>TIPS UNTUK MEMAHAMI</strong>'+esc(l.tip)+'</div>'+glossary()+'</section><section class="card"><h2>Lihat dan ucapkan</h2>'+l.examples.map(e=>'<div class="example">'+audio(e.en)+'<div><div class="example-en" lang="en">'+esc(e.en)+'</div><div class="example-id">'+esc(e.id)+'</div></div></div>').join('')+'<p class="source-caption">Audio perlu suara Inggris di perangkatmu. Jika tidak tersedia, contoh tetap bisa dibaca. Pilihan audio ada di Hasil belajar.</p></section>'+
      '<section class="card"><h2>Coba tanpa melihat</h2><p class="muted">Tutup contoh sebentar. Ucapkan satu kalimat tentang dirimu memakai pola ini. Bandingkan dengan contoh, lalu periksa sendiri.</p><ul class="checklist"><li><input id="say-subject" type="checkbox"><label for="say-subject">Saya sudah menyebut siapa atau apa yang dibicarakan.</label></li><li><input id="say-pattern" type="checkbox"><label for="say-pattern">Saya sudah mengecek pola dan arti kalimat.</label></li><li><input id="say-repeat" type="checkbox"><label for="say-repeat">Saya mencoba mengucapkannya sekali lagi.</label></li></ul><p class="source-caption">Cek mandiri ini tidak direkam dan tidak dinilai otomatis.</p></section></div><aside class="lesson-aside"><div class="eyebrow">SATU LANGKAH HARI INI</div><h3>Siap mencoba?</h3><p>Lima latihan: pahami arti, pilih pola, lengkapi, susun, lalu tulis.</p>'+button(resume?'Lanjutkan latihan':'Mulai 5 latihan','practice/'+id,'gold')+'<div class="small">'+(previous?'Nilai jawaban pertama: '+previous.firstScore+'%. Terbaik: '+previous.bestScore+'%.':'Keliru? Kamu mendapat penjelasan dan bisa mencoba lagi.')+'</div><a href="#path">← Kembali ke daftar pelajaran</a></aside></div><p class="source-caption">'+(l.unit?'Topik dipetakan ke Unit '+l.unit+' Essential Grammar in Use.':'Materi pengantar untuk pemula total.')+' Penjelasan, contoh, dan soal aplikasi ditulis baru.</p>';
  }
  function beginLesson(id){const l=lessons.get(id);if(!l)return false;
    if(quiz?.kind==='lesson'&&quiz.key===id)return true;
    if(state.active?.lesson!==id)state.active={lesson:id,index:0,first:[null,null,null,null,null]};
    quiz={kind:'lesson',key:id,title:l.title,items:K.questions(l),index:state.active.index,first:[...state.active.first],solved:false,selected:null,order:[],feedback:null};save();return true;
  }
  function beginReview(){const ids=K.due(state).slice(0,Math.min(state.settings.goal,15));if(!ids.length){go('review');return;}
    quiz={kind:'review',key:'review',title:'Ulangi yang perlu diingat',items:ids.map(id=>{const qs=K.questions(lessons.get(id));const q=qs[state.reviews[id].box%2?1:2];return {...q,lesson:id};}),index:0,first:ids.map(()=>null),solved:false,selected:null,order:[],feedback:null};go('review-session');
  }
  function beginCheck(id){const p=C.paths.find(p=>p.id===id);if(!p)return false;const ids=K.shuffle(p.lessons,K.day()+id).slice(0,5);quiz={kind:'check',key:id,title:'Latihan gabungan · '+p.title,items:ids.map((id,i)=>({...K.questions(lessons.get(id))[i%2?1:2],lesson:id})),index:0,first:ids.map(()=>null),solved:false,selected:null,order:[],feedback:null};return true;}
  function beginDiagnostic(){const ids=['f01','f02','f04','f05','g005','g007','g003','g011','g017','g030','g103','g049'];quiz={kind:'diagnostic',key:'diagnostic',title:'Cek titik awal',items:ids.map(id=>({...K.questions(lessons.get(id))[1],lesson:id})),index:0,first:ids.map(()=>null),solved:false,selected:null,order:[],feedback:null};go('diagnostic/start');}
  function beginListen(){const done=C.lessons.filter(l=>state.completed[l.id]);const pool=done.length>=5?done:C.lessons.filter(l=>!l.unit);const chosen=K.shuffle(pool,K.day()+'listen').slice(0,5);quiz={kind:'listen',key:'listen',title:'Dengarkan & pahami',items:chosen.map((l,i)=>{const ex=l.examples[i%3];return {id:l.id+'-listen',lesson:l.id,type:'listen',label:'Dengar dan pilih arti',prompt:'Dengarkan ungkapannya. Apa artinya?',listenText:ex.en,options:K.shuffle(l.examples.map(e=>e.id),l.id+'listen'),answers:[ex.id],why:'Ungkapan yang diputar: “'+ex.en+'”. Artinya: “'+ex.id+'”.'};}),index:0,first:chosen.map(()=>null),solved:false,selected:null,order:[],feedback:null};go('listen-session');}
  function questionMarkup(q){if(q.type==='choice'||q.type==='listen')return (q.type==='listen'?'<div class="button-row" style="margin:0 0 23px"><button class="btn secondary" data-action="speak" data-text="'+esc(q.listenText)+'">'+icon('audio')+' Putar ungkapan</button><span class="small muted">'+esc(voiceInfo())+'</span></div>':'')+'<div class="choices">'+q.options.map((o,i)=>'<button class="choice '+(quiz.selected===i?(quiz.solved?'correct':'incorrect'):'')+'" data-action="answer-choice" data-index="'+i+'" '+(quiz.solved?'disabled':'')+'><span class="choice-code">'+String.fromCharCode(65+i)+'</span><span>'+esc(o)+'</span></button>').join('')+'</div>';
    if(q.type==='order')return '<div class="answer-area" id="answer-area">'+orderMarkup(q)+'</div><div class="tokens">'+q.tokens.map(t=>'<button class="token" data-action="add-token" data-index="'+t.i+'" '+(quiz.order.includes(t.i)||quiz.solved?'disabled':'')+'>'+esc(t.word)+'</button>').join('')+'</div><div class="button-row"><button class="btn" data-action="answer-order" '+(quiz.solved?'disabled':'')+'>Periksa kalimat</button><button class="text-link" data-action="clear-tokens" '+(quiz.solved?'disabled':'')+'>Kosongkan</button></div>';
    return '<form id="answer-form"><label for="answer-input" class="input-label">'+(q.type==='gap'?'Tulis kata yang hilang (___).':'Gunakan semua kata dari daftar kata bantuan. Kapital dan tanda akhir boleh berbeda.')+'</label><input class="answer-input" id="answer-input" autocomplete="off" autocapitalize="none" spellcheck="false" '+(quiz.solved?'disabled':'')+' placeholder="Tulis jawabanmu…" aria-describedby="'+(q.type==='write'?'word-bank':'answer-help')+'">'+(q.type==='write'?'<div class="bank-note" id="word-bank"><strong>Bank kata</strong>'+esc(q.bank)+'</div>':'<p class="practice-footnote" id="answer-help">Ikuti pola dan petunjuk yang diberikan.</p>')+'<div class="button-row"><button class="btn" type="submit" '+(quiz.solved?'disabled':'')+'>Periksa jawaban '+icon('arrow')+'</button></div></form>';
  }
  function orderMarkup(q){return quiz.order.length?quiz.order.map(i=>{const token=q.tokens.find(t=>t.i===i);return '<button class="token" data-action="remove-token" data-index="'+i+'" '+(quiz.solved?'disabled':'')+' aria-label="Hapus kata '+esc(token.word)+'">'+esc(token.word)+'</button>';}).join(''):'<span class="answer-placeholder">Klik kata sesuai urutan. Klik kata di sini untuk menghapus.</span>';}
  function feedbackMarkup(){const q=quiz.items[quiz.index];if(!quiz.feedback)return '';
    return '<div class="feedback '+(quiz.feedback.correct?'':'wrong')+'" role="status"><strong>'+(quiz.feedback.correct?'Ya, kamu dapat polanya.':quiz.feedback.hint?'Lihat, pahami, lalu coba.':'Belum pas. Coba sekali lagi.')+'</strong><p>'+esc(q.why)+'</p>'+(!quiz.feedback.correct?'<p class="answer-model">Jawaban yang dituju: '+esc(q.answers[0])+'</p>':'')+(quiz.solved?'<div class="button-row"><button class="btn" data-action="next-question">'+(quiz.index===quiz.items.length-1?'Lihat hasil':'Lanjut')+' '+icon('arrow')+'</button></div>':'')+'</div>';
  }
  function viewQuiz(){if(!quiz)return viewReview();const q=quiz.items[quiz.index], back=quiz.kind==='lesson'?'lesson/'+quiz.key:quiz.kind==='diagnostic'?'home':quiz.kind==='check'?'checks':quiz.kind==='listen'?'listen':'review';
    return '<div class="practice-shell"><div class="practice-header"><a href="#'+back+'">← Kembali</a><span class="practice-count">'+(quiz.index+1)+' / '+quiz.items.length+' latihan</span></div>'+progress(pct(quiz.index,quiz.items.length),'Latihan selesai dalam sesi')+'<section class="card practice-card"><div class="question-kind">'+esc(q.label)+' · '+esc(quiz.title)+'</div><h1>'+esc(q.prompt)+'</h1>'+questionMarkup(q)+'<div id="quiz-feedback" aria-live="polite">'+feedbackMarkup()+'</div><div class="button-row" id="hint-row" '+(quiz.solved?'hidden':'')+'><button class="text-link" data-action="hint">'+(quiz.kind==='listen'?'Buka teks dan arti sebagai bantuan':'Tampilkan jawaban')+'</button></div></section><p class="practice-footnote">Hasil sesi memakai jawaban pertama. Petunjuk dihitung sebagai bantuan. Kamu tetap bisa menyelesaikan latihan setelah memahami jawabannya.</p></div>';
  }
  function answer(value,index=null){if(!quiz||quiz.solved)return;const q=quiz.items[quiz.index];if(!String(value).trim()){toast('Isi jawaban dulu.');return;}const correct=q.type==='choice'||q.type==='listen'?q.answers.includes(value):K.equivalent(value,q.answers);if(quiz.first[quiz.index]===null)quiz.first[quiz.index]=correct;quiz.solved=correct;quiz.selected=index;quiz.feedback={correct};if(quiz.kind==='lesson'){state.active.first=[...quiz.first];save();}
    if(q.type==='choice'||q.type==='listen'){document.querySelectorAll('.choice').forEach((el,i)=>{el.classList.remove('correct','incorrect');if(i===index)el.classList.add(correct?'correct':'incorrect');el.disabled=correct;});}
    else if(correct){document.querySelectorAll('#answer-form input,#answer-form button,.tokens button,.answer-area button,[data-action="answer-order"],[data-action="clear-tokens"]').forEach(el=>el.disabled=true);}
    document.getElementById('quiz-feedback').innerHTML=feedbackMarkup();document.getElementById('hint-row').hidden=correct;
    if(correct)document.querySelector('[data-action="next-question"]').focus();
  }
  function hint(){if(!quiz||quiz.solved)return;if(quiz.first[quiz.index]===null)quiz.first[quiz.index]=false;quiz.feedback={correct:false,hint:true};if(quiz.kind==='lesson'){state.active.first=[...quiz.first];save();}document.getElementById('quiz-feedback').innerHTML=feedbackMarkup();}
  function nextQuestion(){if(!quiz?.solved)return;const q=quiz.items[quiz.index];if(quiz.kind==='review'){state.reviews[q.lesson]=K.schedule(state.reviews[q.lesson],quiz.first[quiz.index]);K.record(state,'review',q.lesson,1);save();}
    if(quiz.index===quiz.items.length-1){finishQuiz();return;}
    quiz.index++;quiz.solved=false;quiz.selected=null;quiz.order=[];quiz.feedback=null;if(quiz.kind==='lesson'){state.active.index=quiz.index;state.active.first=[...quiz.first];save();}main.innerHTML=viewQuiz();main.focus();window.scrollTo(0,0);
  }
  function finishQuiz(){const result={kind:quiz.kind,key:quiz.key,score:pct(quiz.first.filter(Boolean).length,quiz.first.length),first:[...quiz.first],items:quiz.items,title:quiz.title};
    if(quiz.kind==='lesson'){Object.assign(result,K.finishLesson(state,quiz.key,quiz.first));save();lastResult=result;quiz=null;go('done/'+result.key);}
    else {if(quiz.kind==='check'){K.record(state,'check',quiz.key,quiz.items.length);save();}if(quiz.kind==='listen'){for(const q of quiz.items)K.record(state,'listen',q.lesson,1);save();}lastResult=result;quiz=null;go('session-done');}
  }
  function speakTask(prompt,model){return '<div class="speak-task"><h2>Sekarang, pakai dengan suaramu</h2><p>'+esc(prompt)+'</p><details><summary>Lihat contoh bantuan</summary><p lang="en">'+esc(model)+'</p>'+audio(model)+'</details><ul class="checklist"><li><input id="self-meaning" type="checkbox"><label for="self-meaning">Saya tahu arti kalimat yang saya ucapkan.</label></li><li><input id="self-form" type="checkbox"><label for="self-form">Saya mengecek pola dan mengulang sekali.</label></li></ul><p class="source-caption">Latihan mandiri. Tidak direkam, tidak diberi nilai pengucapan otomatis.</p></div>';}
  function viewDone(id){const l=lessons.get(id), completed=state.completed[id];if(!l||!completed)return viewNotFound();const r=lastResult?.kind==='lesson'&&lastResult.key===id?lastResult:null;
    const ordered=C.paths.flatMap(p=>p.lessons),next=ordered[ordered.indexOf(id)+1];
    return '<div class="practice-shell"><section class="card finish-card"><div class="finish-mark" aria-hidden="true">✓</div><div class="eyebrow" style="margin-top:23px">SATU LANGKAH SELESAI</div><h1>'+esc(l.title)+'</h1><p class="muted">Kamu sudah mencoba kelima latihan dan memperbaiki jawabannya.</p><div class="score-grid"><div class="score-cell"><strong>'+(r?r.score:completed.firstScore)+'%</strong><span>'+(r?'Benar pada percobaan pertama sesi ini':'Benar pada sesi pertama')+'</span></div><div class="score-cell"><strong>'+(r?.isNew?'+30':'✓')+'</strong><span>'+(r?.isNew?'Poin untuk pelajaran baru':'Hasil belajar tetap tercatat')+'</span></div></div><p class="small muted">'+((r?r.score:completed.firstScore)<80?'Topik ini masuk antrean pengulangan hari ini. Itu bantuan untuk belajar, bukan hukuman.':'Topik ini akan diulang sesuai jadwal di menu Ulangi.')+'</p>'+speakTask('Ucapkan satu kalimat tentang dirimu atau lingkunganmu dengan pola “'+l.pattern+'”.',l.examples[0].en)+'<div class="button-row">'+(next?button('Langkah berikutnya '+icon('arrow'),'lesson/'+next):button('Coba misi percakapan','missions'))+button('Cukup untuk hari ini','home','secondary')+'</div><a class="text-link" href="#lesson/'+id+'">Baca penjelasan lagi</a></section></div>';
  }
  function viewSessionDone(){const r=lastResult;if(!r)return viewHome();const weak=r.items.filter((q,i)=>!r.first[i]).map(q=>q.lesson);const unique=[...new Set(weak)];
    return '<div class="practice-shell"><section class="card finish-card"><div class="finish-mark" aria-hidden="true">✓</div><div class="eyebrow" style="margin-top:22px">SESI SELESAI</div><h1>'+esc(r.title)+'</h1><div class="score-grid"><div class="score-cell"><strong>'+r.first.filter(Boolean).length+' / '+r.first.length+'</strong><span>Benar pada jawaban pertama</span></div><div class="score-cell"><strong>'+(r.kind==='review'?'Jadwal diperbarui':'Selesai dicek')+'</strong><span>'+(r.kind==='review'?'Jawaban benar membuat jadwal berikutnya lebih jauh':'Bantuan memilih langkah')+'</span></div></div><p class="muted">'+(r.kind==='diagnostic'?(r.score<60?'Mulai dari delapan pelajaran Titik nol. Tidak perlu terburu-buru.':'Kamu bisa mulai dari topik yang masih perlu diperkuat. Semua pelajaran tetap terbuka.'):'Jawaban yang belum tepat memberi petunjuk materi yang perlu dibaca lagi.')+'</p>'+(unique.length?'<div style="text-align:left;margin-top:24px"><h2 style="font-size:19px">Baca ulang pilihan ini</h2><div class="lesson-list">'+unique.slice(0,4).map(id=>lessonRow(lessons.get(id))).join('')+'</div></div>':'<p class="encourage">Semua jawaban pertama tepat. Coba gunakan satu pola dalam kalimatmu sendiri.</p>')+'<div class="button-row">'+button(r.kind==='diagnostic'?'Mulai langkah yang disarankan':'Kembali belajar',r.kind==='diagnostic'?(r.score<60?'lesson/f01':unique.length?'lesson/'+unique[0]:'lesson/g001'):unique.length?'lesson/'+unique[0]:'home')+button('Lihat pelajaran','path','secondary')+'</div><p class="source-caption">'+(r.kind==='diagnostic'?'Cek 12 soal ini bukan tes tingkat kemampuan bahasa Inggris (CEFR) dan tidak menetapkan tingkat kelancaran berbahasa.':'Hasil latihan bukan sertifikat atau ukuran kelancaran berbahasa.')+'</p></section></div>';
  }
  function viewReview(){const ids=K.due(state), upcoming=Object.entries(state.reviews).filter(([id,r])=>r.due>K.day()).sort((a,b)=>a[1].due.localeCompare(b[1].due));
    return heading('LATIHAN MENGINGAT KEMBALI','Biar ingatnya lebih lama.','Coba mengingat sebelum membuka catatan. Jawaban yang tepat memperpanjang jeda pengulangan.')+'<div class="review-grid"><section class="card"><div class="card-topline"><h2>Menunggu hari ini</h2>'+badge(ids.length+' topik')+'</div>'+(ids.length?'<p class="muted">Sesi ini berisi maksimal '+state.settings.goal+' topik. Satu soal per topik; kamu boleh membaca penjelasan setelahnya.</p><div class="button-row"><button class="btn" data-action="start-review">Mulai pengulangan '+icon('arrow')+'</button></div><div style="margin-top:17px">'+ids.slice(0,20).map(id=>'<div class="review-item"><div><strong>'+esc(lessons.get(id).title)+'</strong><p>'+esc(C.paths[lessons.get(id).stage].title)+'</p></div><a class="text-link" href="#lesson/'+id+'">Baca</a></div>').join('')+'</div>':'<div class="empty" style="margin-top:21px"><h2>'+(Object.keys(state.completed).length?'Belum ada yang perlu diulang hari ini.':'Mulai satu langkah dulu.')+'</h2><p>'+(upcoming.length?'Pengulangan berikutnya: '+esc(upcoming[0][1].due)+'. Kamu tetap bisa membuka materi kapan saja.':'Setelah menyelesaikan pelajaran, jadwal pengulangan akan dibuat otomatis.')+'</p>'+button('Lanjut belajar','lesson/'+nextLesson().id)+'</div>')+'</section><aside class="card review-note"><div class="eyebrow">CARA KERJANYA</div><h2>Jeda yang mengikuti latihanmu.</h2><ol><li>Nilai awal di bawah 80%: topik muncul lagi hari ini. Jika cukup tepat: mulai besok.</li><li>Jawaban ulang pertama yang tepat memberi jeda 1, 3, 7, 14, lalu 30 hari.</li><li>Jika perlu bantuan atau keliru, jadwal kembali besok. Kamu tetap memperbaiki jawaban sekarang.</li></ol><p>Jadwal ini memakai aturan sederhana. Jeda yang paling cocok bisa berbeda untuk setiap orang.</p><a class="text-link" href="#words">Ulangi kosakata juga →</a></aside></div>';
  }
  function wordResults(){const list=C.vocab.filter(w=>(w.en+' '+w.meaning).toLowerCase().includes(wordFilters.search.toLowerCase())&&(wordFilters.group==='all'||w.group===wordFilters.group));return '<p class="filter-result">'+list.length+' kata • Arti mengikuti konteks dasar; satu kata bisa punya makna lain.</p><div class="word-grid">'+list.map(w=>'<article class="card word-card"><div class="word-card-top"><strong lang="en">'+esc(w.en)+'</strong>'+audio(w.en)+'</div><p>'+esc(w.meaning)+'</p>'+badge(w.group,'neutral')+'</article>').join('')+'</div>'+(list.length?'':'<div class="empty"><h2>Kata belum ditemukan.</h2><p>Coba kata Inggris atau arti Indonesianya.</p></div>');}
  function viewWords(){return heading('KOSAKATA','Kumpulkan kata yang berguna.','Dengarkan, pahami, lalu coba ingat artinya tanpa melihat.')+'<div class="word-toolbar"><button class="btn" data-action="start-words">Latih 10 kartu '+icon('arrow')+'</button><a class="btn secondary" href="#reference">Kata kerja tidak beraturan</a></div><div class="filter-bar"><label class="search-wrap">'+icon('search')+'<input type="search" id="word-search" aria-label="Cari kosakata" placeholder="Cari kata atau arti…" value="'+esc(wordFilters.search)+'"></label><select id="word-group" aria-label="Kelompok kosakata"><option value="all">Semua kelompok</option>'+Object.keys(Object.fromEntries(C.vocab.map(w=>[w.group,true]))).map(g=>'<option '+(wordFilters.group===g?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select></div><div id="word-results">'+wordResults()+'</div>';}
  function startWords(){const today=K.day();const due=C.vocab.filter(w=>state.words[w.id]&&state.words[w.id].due<=today), fresh=C.vocab.filter(w=>!state.words[w.id]);let list=[...due,...fresh].slice(0,10);let practice=false;if(!list.length){list=K.shuffle(C.vocab,today).slice(0,10);practice=true;}wordSession={list,index:0,revealed:false,remembered:0,practice};go('word-flash');}
  function viewFlash(){if(!wordSession)return viewWords();const s=wordSession,w=s.list[s.index];if(!w)return '<div class="practice-shell"><section class="card finish-card"><div class="finish-mark">✓</div><h1>Kartu selesai, satu langkah.</h1><p class="muted">Kamu menilai “ingat” pada '+s.remembered+' dari '+s.list.length+' kartu. Ini penilaian mandiri, bukan tes otomatis.</p><div class="button-row">'+button('Kembali ke kosakata','words')+button('Lanjut belajar','home','secondary')+'</div></section></div>';
    return '<div class="practice-shell"><div class="practice-header"><a href="#words">← Kosakata</a><span class="practice-count">'+(s.index+1)+' / '+s.list.length+'</span></div>'+progress(pct(s.index,s.list.length),'Kartu kosakata selesai')+'<section class="card flashcard" style="margin-top:24px"><div class="eyebrow">COBA INGAT ARTINYA</div>'+badge(w.group,'neutral')+'<div class="flash-word" lang="en">'+esc(w.en)+'</div>'+audio(w.en)+(s.revealed?'<div class="flash-meaning">'+esc(w.meaning)+'</div><p class="small muted">Nilai dirimu dengan jujur. Melihat arti bukan berarti gagal.</p><div class="button-row"><button class="btn secondary" data-action="word-grade" data-correct="false">Belum ingat</button><button class="btn" data-action="word-grade" data-correct="true">Saya ingat</button></div>':'<p class="muted">Ucapkan artinya dulu, lalu buka jawabannya.</p><div class="button-row"><button class="btn" data-action="reveal-word">Lihat arti</button></div>')+'</section><p class="practice-footnote">'+(s.practice?'Semua kata sudah terjadwal. Sesi tambahan ini tidak mengubah jeda waktu.':'Kartu yang diingat akan dijadwalkan dengan jeda 1, 3, 7, 14, dan 30 hari. Kartu yang belum diingat kembali besok.')+'</p></div>';
  }
  function tabs(selected){return '<div class="tabs" aria-label="Pilihan latihan"><a class="tab '+(selected==='missions'?'active':'')+'" href="#missions">Percakapan</a><a class="tab '+(selected==='checks'?'active':'')+'" href="#checks">Latihan gabungan</a><a class="tab '+(selected==='diagnostic'?'active':'')+'" href="#diagnostic">Cek titik awal</a><a class="tab '+(selected==='listen'?'active':'')+'" href="#listen">Dengar</a></div>';}
  function viewMissions(){return heading('LATIHAN PERCAKAPAN','Bawa Inggris ke keseharian.','Baca percakapan pendek, pilih jawaban, lalu ucapkan versimu sendiri.')+tabs('missions')+'<div class="mission-grid">'+C.missions.map((m,i)=>'<section class="card mission-card"><div class="card-topline">'+badge(m.place,'gold')+'<span class="small muted">Misi '+String(i+1).padStart(2,'0')+'</span></div><h2>'+esc(m.title)+'</h2><p>'+esc(m.speak)+'</p><div class="button-row">'+button(state.missions[m.id]?'Latih lagi':'Buka percakapan','mission/'+m.id,'sm')+(state.missions[m.id]?badge('Sudah dicoba'):'')+'</div></section>').join('')+'</div><div class="encourage">Kosakata belum cukup? <a class="text-link" href="#words">Mulai dari kata dasar →</a></div>';}
  function viewMission(id){const m=C.missions.find(m=>m.id===id);if(!m)return viewNotFound();if(missionFeedback?.id!==id)missionFeedback=null;return '<div class="practice-shell">'+heading(m.place,m.title,'Latihan percakapan dengan bantuan arti Indonesia.')+'<section class="card"><h2>Ikuti percakapannya</h2><div class="dialogue">'+m.lines.map(([speaker,en,idn])=>'<div class="dialogue-line"><span class="speaker">'+esc(speaker==='You'?'Kamu':speaker==='Seller'?'Penjual':speaker)+'</span><div><p lang="en">'+esc(en)+'</p><small>'+esc(idn)+'</small></div>'+audio(en)+'</div>').join('')+'</div><h2 class="mission-prompt">'+esc(m.prompt)+'</h2><div class="choices" style="margin-top:21px">'+K.shuffle(m.options,m.id).map((o,i)=>'<button class="choice" data-action="mission-answer" data-id="'+m.id+'" data-value="'+esc(o)+'" '+(missionFeedback?.correct?'disabled':'')+'><span class="choice-code">'+String.fromCharCode(65+i)+'</span>'+esc(o)+'</button>').join('')+'</div><div id="mission-feedback" aria-live="polite">'+missionFeedbackMarkup(m)+'</div>'+speakTask(m.speak,m.model)+'<p class="source-caption">Satu soal pilihan diperiksa otomatis. Praktik berbicara diperiksa sendiri.</p><div class="button-row">'+button('Kembali ke misi','missions','secondary')+'</div><details class="glossary"><summary>Topik yang membantu misi ini</summary>'+m.units.map(id=>'<a class="text-link" style="display:block" href="#lesson/'+id+'">'+esc(lessons.get(id).title)+' →</a>').join('')+'</details></section></div>';}
  function missionFeedbackMarkup(m){if(!missionFeedback)return '';return '<div class="feedback '+(missionFeedback.correct?'':'wrong')+'" role="status"><strong>'+(missionFeedback.correct?'Jawabannya sudah pas.':'Mari cek polanya.')+'</strong><p>'+esc(m.why)+'</p>'+(missionFeedback.correct?'<p>Misi tercatat. Sekarang coba bagian berbicara di bawah.</p>':'<p>Jawaban: '+esc(m.options[m.answer])+'. Coba pilih lagi.</p>')+'</div>';}
  function viewChecks(){return heading('LATIHAN GABUNGAN','Coba membedakan, bukan menebak.','Lima soal dari beberapa topik satu tahap. Baca materinya lebih dahulu jika masih baru.')+tabs('checks')+'<div class="checkpoint-list">'+C.paths.map(p=>'<section class="card checkpoint-card"><div class="eyebrow">TAHAP '+p.id.slice(1)+'</div><h2>'+esc(p.title)+'</h2><p>'+p.lessons.filter(id=>state.completed[id]).length+' dari '+p.lessons.length+' pelajaran sudah dicoba. Latihan ini tidak menandai pelajaran sebagai selesai.</p><div class="button-row">'+button('Coba 5 soal','check/'+p.id,'sm')+'</div></section>').join('')+'</div>';}
  function viewDiagnostic(){return heading('CEK TITIK AWAL','Mulai di tempat yang nyaman.','Opsional. Dua belas pilihan singkat untuk mencari topik yang perlu dibantu.')+tabs('diagnostic')+'<section class="card diagnostic-intro"><h2>Boleh belum tahu jawabannya.</h2><ul><li>Coba tanpa membaca catatan. Jika belum tahu, tombol “Tampilkan jawaban” akan membantu.</li><li>Hasil memberi saran jalur, tidak mengunci materi atau menetapkan tingkat kemampuan bahasa Inggris (CEFR).</li><li>Jika betul-betul baru, kamu bisa langsung mulai dari Titik nol.</li></ul><div class="button-row"><button class="btn" data-action="start-diagnostic">Mulai 12 soal</button>'+button('Mulai dari nol','lesson/f01','secondary')+'</div></section>';}
  function viewListen(){return heading('LATIHAN MENDENGAR','Dengar dulu, cari maknanya.','Lima ungkapan dari pelajaran yang sudah dicoba, atau ungkapan pengantar jika kamu baru mulai.')+tabs('listen')+'<section class="card diagnostic-intro"><h2>Satu ungkapan, boleh diputar lagi.</h2><p class="muted">'+esc(voiceInfo())+'</p><ol><li>Tekan Putar ungkapan. Coba pilih arti tanpa melihat tulisan Inggris.</li><li>Boleh memutar lagi. Jika belum terdengar atau belum paham, buka teks dan arti sebagai bantuan.</li><li>Setelah latihan, tirukan satu ungkapan. Kualitas audio bergantung pada suara perangkat, bukan rekaman manusia dari buku.</li></ol><div class="button-row"><button class="btn" data-action="start-listen">Mulai 5 ungkapan '+icon('audio')+'</button><a class="btn secondary" href="#progress">Pengaturan audio</a></div><p class="source-caption">Aplikasi tidak bisa memastikan apakah kamu benar-benar mendengarkan suaranya. Jika menggunakan teks bantuan, gunakan sesi ini sebagai latihan membaca dan memahami arti.</p></section>';}
  function viewProgress(){const count=Object.keys(state.completed).length,stable=Object.values(state.reviews).filter(r=>r.box>=3).length;let activity='';for(let i=13;i>=0;i--){const d=K.plusDays(K.day(),-i),n=K.daily(state,d);activity+='<span class="activity-day '+(n?'has':'')+'" title="'+d+': '+n+' latihan" aria-label="'+d+': '+n+' latihan">'+d.slice(-2)+'</span>';}
    return heading('HASIL BELAJAR & PENGATURAN','Lihat langkah yang sudah kamu ambil.','Hasil belajar tersimpan pada browser dan perangkat ini. Unduh cadangan agar bisa dipindahkan.')+'<div class="stats-grid">'+[['Pelajaran selesai',count,'dari 123 langkah'],['Ingat saat mengulang',stable,'minimal 3 ulang tepat berturut-turut'],['Hari beruntun',K.streak(state),'hari aktif belajar'],['Poin latihan',K.xp(state),'poin, bukan ukuran kelancaran berbahasa']].map(([label,num,sub])=>'<section class="card stat-card"><div class="small">'+esc(label)+'</div><strong>'+num+'</strong><p>'+esc(sub)+'</p></section>').join('')+'</div><div class="progress-layout"><div><section class="card"><h2>Jejak 14 hari terakhir</h2><p class="small muted">Hijau = ada latihan tercatat. Tanggal memakai waktu lokal perangkatmu.</p><div class="activity">'+activity+'</div></section><section class="card"><h2>Jalur yang sudah dicoba</h2>'+C.paths.map(p=>{const done=p.lessons.filter(id=>state.completed[id]).length;return '<div style="margin-top:20px"><div class="card-topline"><strong class="small">'+esc(p.title)+'</strong><span class="small muted">'+done+' / '+p.lessons.length+'</span></div>'+progress(pct(done,p.lessons.length),p.title)+'</div>';}).join('')+'</section><section class="card backup-box"><h2>Bawa hasil belajarmu</h2><p>Cadangan berisi nilai dan jadwal, tanpa identitas pribadi. Membuka file cadangan akan mengganti hasil belajar di browser ini setelah kamu menyetujuinya.</p><div class="button-row"><button class="btn secondary" data-action="export">Unduh cadangan</button><button class="btn secondary" data-action="import">Buka file cadangan</button><input type="file" class="file-input" id="import-file" accept=".json,application/json" aria-label="Pilih cadangan JSON"></div><p class="source-caption">Membersihkan data browser, mode privat, atau berpindah alamat situs bisa menghapus/memisahkan hasil belajar.</p></section></div><div><section class="card"><form class="settings-form" id="settings-form"><h2>Sesuaikan ritmemu</h2><div class="field"><label for="daily-goal">Target latihan per hari</label><select id="daily-goal"><option value="5" '+(state.settings.goal===5?'selected':'')+'>5 latihan · santai</option><option value="10" '+(state.settings.goal===10?'selected':'')+'>10 latihan · rutin</option><option value="15" '+(state.settings.goal===15?'selected':'')+'>15 latihan · lebih banyak</option></select><p class="hint">Ini jumlah soal/kartu, bukan janji durasi.</p></div><div class="field"><label for="speech-rate">Kecepatan audio</label><select id="speech-rate"><option value="0.65" '+(state.settings.rate===.65?'selected':'')+'>Pelan</option><option value="0.85" '+(state.settings.rate===.85?'selected':'')+'>Nyaman</option><option value="1" '+(state.settings.rate===1?'selected':'')+'>Normal</option></select><p class="hint" id="voice-info">'+esc(voiceInfo())+'</p></div><label class="checkbox-field"><input type="checkbox" id="remote-voice" '+(state.settings.remote?'checked':'')+'><span>Izinkan suara melalui internet bila suara Inggris dari perangkat tidak ada. Teks bisa dikirim oleh browser ke penyedia suara. Internet mungkin diperlukan.</span></label><button class="btn" type="submit">Simpan pengaturan</button><button class="btn secondary" type="button" data-action="speak" data-text="Hello. I am learning English.">Coba audio '+icon('audio')+'</button></form></section><section class="card"><h2>Apa arti angkanya?</h2><p class="small muted">Selesai = lima latihan telah dicoba dan jawabannya diperbaiki. Ingat saat mengulang = tiga jawaban ulang pertama tepat berturut-turut. Poin diberikan untuk kegiatan belajar, bukan bukti sudah lancar berbahasa Inggris.</p><a class="text-link" href="#about">Baca panduan belajar →</a></section><section class="card danger-zone"><h2>Mulai ulang</h2><p>Hapus nilai, jadwal, misi, dan pengaturan di browser ini. Unduh cadangan dulu jika ingin menyimpannya.</p><div class="button-row"><button class="btn secondary" data-action="reset">Hapus hasil belajar</button></div></section></div></div>';
  }
  function voiceInfo(){const english=voices.filter(v=>/^en(?:-|$)/i.test(v.lang));return english.some(v=>v.localService)?'Suara Inggris dari perangkat tersedia.':english.length?'Hanya suara Inggris melalui internet yang tersedia. Aktifkan izin jika ingin memakainya.':'Suara Inggris belum tersedia. Coba browser/perangkat lain atau pasang suara Inggris di pengaturan perangkat.';}
  function viewAbout(){return heading('PANDUAN & SUMBER','Belajar sedikit, pakai sedikit.','Cara belajar, batas aplikasi, serta sumber yang digunakan.')+'<div class="about-layout"><section class="card"><h2>Cara memakai Langkah</h2><ol><li>Mulai dari delapan pelajaran Titik nol jika belum mengenal bahasa Inggris.</li><li>Pahami penjelasan dan contoh. Ucapkan satu contoh, lalu coba lima latihan tanpa menyalin.</li><li>Baca alasan saat keliru. Perbaiki jawaban untuk lanjut. Jangan hanya menghafal tombol.</li><li>Buka Ulangi pada hari berikutnya. Setelah beberapa topik, coba Latihan gabungan dan misi percakapan.</li><li>Gunakan satu kalimat dalam kehidupan sehari-hari. Latihan berbicara aplikasi ini diperiksa sendiri.</li></ol><p>Latihan mengingat dan belajar dengan jeda didukung tinjauan Dunlosky dkk. (2013). Urutan belajar dan jeda latihan dipilih sebagai panduan sederhana. Belum terbukti bahwa jadwal ini paling cocok untuk setiap orang Indonesia.</p><a href="https://www.psychologicalscience.org/journals/pspi/1529100612453266/" target="_blank" rel="noopener noreferrer">Baca sumber penelitian ↗</a></section><section class="card"><h2>Buku yang dipelajari</h2><p>Raymond Murphy, <em>Essential Grammar in Use with Answers</em>, edisi keempat, Cambridge University Press, 2015. Seluruh 318 halaman PDF yang tersedia ditelaah: 115 unit, tujuh lampiran, 35 set latihan tambahan, Study Guide yang tersedia, kunci jawaban, dan indeks.</p><p>Berkas memiliki satu halaman kosong (halaman PDF 241) dan tidak memuat halaman cetak 278 pada Study Guide. Bagian yang tidak tersedia tidak diklaim telah dibaca. Buku menyatakan bukan untuk pemula total dan bukan kursus berurutan; aplikasi menambahkan pengantar dan menata ulang jalurnya.</p><p>123 pelajaran dan 615 soal inti aplikasi adalah materi baru. Cakupan memetakan semua 115 topik; aplikasi tidak menyalin semua latihan atau setiap variasi contoh buku. PDF sumber dan teks hasil pindai tidak dibagikan dalam paket.</p><p>Aplikasi ini independen dan tidak berafiliasi dengan penulis atau penerbit. Ragam Britania menjadi acuan sebagian pola; ragam Amerika yang relevan dijelaskan.</p><a class="text-link" href="#reference">Buka ringkasan tujuh kelompok rujukan →</a></section><section class="card"><h2>Suara, data pribadi, dan penggunaan tanpa internet</h2><p>Tidak perlu akun. Aplikasi tidak memakai iklan, pelacak, atau mikrofon. Nilai dan pengaturan disimpan di browser. Hasil belajar tidak otomatis ikut pindah saat kamu berganti perangkat.</p><p>Audio memakai suara bahasa Inggris yang disediakan perangkat/browser. Aplikasi mengutamakan suara dari perangkat dan tidak memakai suara melalui internet tanpa izin pengaturan. Jika tidak ada suara Inggris yang diizinkan, contoh teks tetap tersedia. Kualitas dan ketersediaan suara berbeda-beda.</p><p>Setelah situs berhasil menyimpan materi di perangkat, kamu bisa belajar tanpa internet. Suara yang diputar melalui internet dan tautan sumber tetap memerlukan koneksi. Jika membuka file index.html langsung dari folder, fitur penyimpanan untuk penggunaan tanpa internet tidak diaktifkan.</p><p>Penilaian tulisan terbatas pada soal berpola dengan daftar kata bantuan. Kapital, spasi berlebih, tanda akhir, dan bentuk singkat umum diterima. Jawaban bebas dan pengucapan tidak dinilai otomatis. Website ini membantu dasar tata bahasa dan latihan awal, bukan kursus lengkap semua keterampilan atau sertifikat tingkat kemampuan bahasa Inggris (CEFR).</p></section><section class="card"><h2>Untuk pemilik website</h2><p>Paket memuat kode, panduan GitHub Pages, peta 115 unit, dan catatan pengujian. Upload isi folder website ke repositori dan pilih cabang main serta folder root pada pengaturan Pages.</p><p>Ubah isi di js/content.js. Jika memperbarui aset, naikkan VERSION di sw.js agar pengunjung memperoleh cache baru. Setelah versi baru terpasang, tutup tab lama dan buka lagi.</p><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site" target="_blank" rel="noopener noreferrer">Panduan resmi GitHub Pages ↗</a></section></div>';}
  function viewReference(){return heading('RINGKASAN RUJUKAN','Pola penting, mudah ditemukan.','Ringkasan asli untuk tujuh kelompok lampiran buku. Bukan salinan tabel atau daftar lengkapnya.')+'<div class="about-layout"><section class="card"><h2>1 · Melakukan dan menerima tindakan</h2><p>Aktif: They clean it berarti mereka membersihkannya. Pasif: It is cleaned berarti benda itu dibersihkan.</p><div class="table-wrap"><table><thead><tr><th>Makna</th><th>Melakukan (aktif)</th><th>Menerima tindakan (pasif)</th></tr></thead><tbody><tr><td>Rutin</td><td>They clean it.</td><td>It is cleaned.</td></tr><tr><td>Lampau</td><td>They cleaned it.</td><td>It was cleaned.</td></tr><tr><td>Sedang</td><td>They are cleaning it.</td><td>It is being cleaned.</td></tr><tr><td>Sudah</td><td>They have cleaned it.</td><td>It has been cleaned.</td></tr><tr><td>Akan</td><td>They will clean it.</td><td>It will be cleaned.</td></tr></tbody></table></div><p class="source-caption">Untuk satu benda, it memakai is/was/has. Untuk lebih dari satu benda, they memakai are/were/have.</p></section><section class="card"><h2>2 · Kata kerja tidak beraturan</h2><p class="muted">Bentuk kedua dipakai untuk masa lalu. Bentuk ketiga dipakai setelah have/has atau dalam kalimat pasif seperti is cleaned. Mulai dari beberapa kata yang paling kamu perlukan. Read ejaannya sama tetapi bunyi bentuk kedua dan ketiganya seperti “red”. Get di tabel mengikuti ragam Britania; gotten juga dipakai untuk banyak makna di Amerika.</p><div class="table-wrap"><table><thead><tr><th>Dasar</th><th>Bentuk kedua (lampau)</th><th>Bentuk ketiga</th><th>Arti umum</th></tr></thead><tbody>'+C.irregular.map(row=>'<tr>'+row.map(t=>'<td>'+esc(t)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></section><section class="card"><h2>3 · Kelompok bentuk untuk mengingat</h2><p>Semua sama: put–put–put. Bentuk kedua dan ketiga sama: buy–bought–bought. Ketiganya berbeda: go–went–gone. Bentuk dasar dan ketiga sama: come–came–come.</p><p>Kelompok membantu mengingat, tetapi bukan rumus yang bisa menebak semua kata baru.</p></section><section class="card"><h2>4 · Bentuk singkat, seperti I’m dan don’t</h2><p>I’m = I am; you’re = you are; don’t = do not; can’t = cannot; won’t = will not; I’ll = I will. He’s bisa he is atau he has; I’d bisa I would atau I had. Lihat kata sesudahnya untuk memahami konteks.</p><p>Yes, I am tidak menjadi Yes, I’m dalam jawaban positif singkat. My/mine/yours/hers tidak mendapat tanda ’ untuk kepemilikan.</p></section><section class="card"><h2>5 · Ejaan -s, -ed, dan -ing</h2><p>Watch → watches. Study → studies/studied, tetapi studying. Make → making. Stop → stopped/stopping. Play → played karena sebelum y ada vokal.</p><p>Penggandaan huruf bergantung pada akhir kata dan tekanan bunyi; jangan menambahkan huruf ganda ke setiap kata. Travelled (Britania) dan traveled (Amerika) sama-sama benar.</p></section><section class="card"><h2>6 · Pasangan kata kerja: get up dan come back</h2><p>Get up = bangun; come back = kembali; go out = keluar; sit down = duduk; take off untuk pesawat = lepas landas. Mulai dari contoh yang lengkap agar maknanya jelas.</p></section><section class="card"><h2>7 · Pasangan kata kerja: turn on the light</h2><p>Turn on the light dan turn the light on bisa. Dengan it: turn it on. Pick the bag up/pick up the bag juga bisa; dengan kata ganti: pick it up.</p><p>Look after him tidak dapat dipisah. Aturan pemisahan harus diperiksa untuk tiap phrasal verb baru.</p></section></div>';}
  function viewNotFound(){return '<div class="empty"><h1>Halaman belum ditemukan.</h1><p>Topik ini mungkin tidak ada dalam versi aplikasi ini.</p>'+button('Kembali ke daftar pelajaran','path')+'</div>';}
  function render(){const route=window.LANGKAH_MODULE_CONTEXT?.route||location.hash.slice(1)||'home',parts=route.split('/'),base=parts[0],id=parts[1];updateNav(base);updateStats();let html;
    switch(base){case 'home':html=viewHome();break;case 'path':html=viewPath();break;case 'lesson':html=viewLesson(id);break;case 'practice':html=beginLesson(id)?viewQuiz():viewNotFound();break;case 'done':html=viewDone(id);break;case 'review':html=viewReview();break;case 'review-session':html=quiz?.kind==='review'?viewQuiz():viewReview();break;case 'words':html=viewWords();break;case 'word-flash':html=viewFlash();break;case 'missions':html=viewMissions();break;case 'mission':missionFeedback=null;html=viewMission(id);break;case 'checks':html=viewChecks();break;case 'listen':html=viewListen();break;case 'listen-session':html=quiz?.kind==='listen'?viewQuiz():viewListen();break;case 'check':if(quiz?.kind!=='check'||quiz.key!==id)beginCheck(id);html=quiz?.kind==='check'&&quiz.key===id?viewQuiz():viewNotFound();break;case 'diagnostic':html=id==='start'&&quiz?.kind==='diagnostic'?viewQuiz():viewDiagnostic();break;case 'session-done':html=viewSessionDone();break;case 'progress':html=viewProgress();break;case 'about':html=viewAbout();break;case 'reference':html=viewReference();break;case 'main':html=viewHome();break;default:html=viewNotFound();}
    main.innerHTML=html;document.title=(base==='lesson'&&lessons.has(id)?lessons.get(id).title+' — ':'')+'Langkah English';main.focus({preventScroll:true});window.scrollTo(0,0);
  }
  function loadVoices(){voices=window.speechSynthesis?.getVoices()||[];const el=document.getElementById('voice-info');if(el)el.textContent=voiceInfo();}
  function speak(text){if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){toast('Audio belum didukung browser ini. Kamu tetap bisa membaca dan menirukan teks.');return;}
    loadVoices();const english=voices.filter(v=>/^en(?:-|$)/i.test(v.lang)), local=english.filter(v=>v.localService);const pool=local.length?local:state.settings.remote?english:[];if(!pool.length){toast(voiceInfo()+' Atur audio melalui Hasil belajar.');return;}
    const chosen=pool.find(v=>/^en-GB$/i.test(v.lang))||pool.find(v=>/^en-US$/i.test(v.lang))||pool[0];const utterance=new SpeechSynthesisUtterance(text);utterance.voice=chosen;utterance.lang=chosen.lang;utterance.rate=state.settings.rate;utterance.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('Audio tidak bisa diputar. Baca teksnya atau coba lagi.');};speechSynthesis.cancel();speechSynthesis.speak(utterance);
  }
  function confirmAction(title,body,callback){const dialog=document.getElementById('confirm-dialog');document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').textContent=body;dialog.returnValue='';dialog.showModal();dialog.addEventListener('close',()=>{if(dialog.returnValue==='confirm')callback();},{once:true});}
  function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='langkah-progres-'+K.day()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File cadangan diunduh. Simpan file ini untuk memindahkan hasil belajarmu.');}
  async function importBackup(file){if(!file)return;if(file.size>700000){toast('File terlalu besar. Pilih file cadangan Langkah (.json) di bawah 700 KB.');return;}try{const text=await file.text();if(/"(?:__proto__|constructor|prototype)"\s*:/.test(text))throw Error('Kunci data tidak valid.');pendingBukat=K.validated(JSON.parse(text),C);confirmAction('Ganti hasil belajar dengan cadangan?','Cadangan ini memuat '+Object.keys(pendingBukat.completed).length+' pelajaran selesai. Hasil belajar saat ini akan diganti. Unduh cadangan lama jika masih diperlukan.',()=>{state=pendingBukat;pendingBukat=null;quiz=null;lastResult=null;wordSession=null;save();render();toast('Cadangan berhasil dipulihkan.');});}catch(e){toast('Cadangan ditolak: '+(e instanceof SyntaxError?'Isi file cadangan tidak dapat dibaca.':e.message));}}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
    switch(action){case 'speak':speak(el.dataset.text);break;case 'clear-filter':filters={search:'',stage:'all',status:'all'};render();break;case 'answer-choice':{const i=Number(el.dataset.index);answer(quiz.items[quiz.index].options[i],i);break;}case 'hint':hint();break;case 'next-question':nextQuestion();break;case 'add-token':{quiz.order.push(Number(el.dataset.index));main.innerHTML=viewQuiz();(document.querySelector('.tokens .token:not(:disabled)')||document.querySelector('[data-action="answer-order"]'))?.focus();break;}case 'remove-token':{quiz.order=quiz.order.filter(i=>i!==Number(el.dataset.index));main.innerHTML=viewQuiz();document.querySelector('.tokens .token:not(:disabled)')?.focus();break;}case 'clear-tokens':quiz.order=[];main.innerHTML=viewQuiz();document.querySelector('.tokens .token:not(:disabled)')?.focus();break;case 'answer-order':{const q=quiz.items[quiz.index];answer(quiz.order.map(i=>q.tokens.find(t=>t.i===i).word).join(' '));break;}case 'start-review':beginReview();break;case 'start-diagnostic':beginDiagnostic();break;case 'start-listen':beginListen();break;case 'start-words':startWords();break;case 'reveal-word':if(wordSession){wordSession.revealed=true;main.innerHTML=viewFlash();}break;case 'word-grade':{if(!wordSession?.revealed)return;const w=wordSession.list[wordSession.index],correct=el.dataset.correct==='true';if(correct)wordSession.remembered++;if(!wordSession.practice)state.words[w.id]=K.schedule(state.words[w.id],correct);K.record(state,'word',w.id,1);wordSession.index++;wordSession.revealed=false;save();main.innerHTML=viewFlash();main.focus();break;}case 'mission-answer':{const m=C.missions.find(m=>m.id===el.dataset.id),correct=el.dataset.value===m.options[m.answer];missionFeedback={id:m.id,correct};if(correct){if(!state.missions[m.id]){state.missions[m.id]={date:K.day()};K.record(state,'mission',m.id,1);save();}document.querySelectorAll('[data-action="mission-answer"]').forEach(b=>b.disabled=true);}document.getElementById('mission-feedback').innerHTML=missionFeedbackMarkup(m);break;}case 'export':exportBackup();break;case 'import':document.getElementById('import-file').click();break;case 'reset':confirmAction('Hapus seluruh hasil belajar di browser ini?','Nilai, jadwal, kosakata, misi, sesi tersimpan, dan pengaturan akan dihapus. File cadangan yang pernah diunduh tetap bisa dibuka kembali.',()=>{state=K.initialState();quiz=null;lastResult=null;wordSession=null;missionFeedback=null;save();render();toast('Hasil belajar dihapus. Kamu bisa mulai lagi dari Titik nol.');});break;}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();answer(document.getElementById('answer-input').value);}if(e.target.id==='settings-form'){e.preventDefault();state.settings={goal:Number(document.getElementById('daily-goal').value),rate:Number(document.getElementById('speech-rate').value),remote:document.getElementById('remote-voice').checked};save();toast('Ritme belajarmu disimpan.');}});
  document.addEventListener('input',e=>{if(e.target.id==='lesson-search'){filters.search=e.target.value;document.getElementById('path-results').innerHTML=pathResults();}if(e.target.id==='word-search'){wordFilters.search=e.target.value;document.getElementById('word-results').innerHTML=wordResults();}});
  document.addEventListener('change',e=>{if(e.target.id==='stage-filter'||e.target.id==='status-filter'){filters[e.target.id==='stage-filter'?'stage':'status']=e.target.value;document.getElementById('path-results').innerHTML=pathResults();}if(e.target.id==='word-group'){wordFilters.group=e.target.value;document.getElementById('word-results').innerHTML=wordResults();}if(e.target.id==='import-file')importBackup(e.target.files[0]);});
  window.addEventListener('hashchange',()=>{window.speechSynthesis?.cancel();render();});
  window.addEventListener('online',()=>toast('Koneksi tersedia.'));
  if(window.speechSynthesis){loadVoices();speechSynthesis.addEventListener('voiceschanged',loadVoices);}
  document.getElementById('offline-status').textContent='Materi berada dalam aplikasi Langkah English.';
  function registerModelTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const toolResult=value=>({content:[{type:'text',text:JSON.stringify(value)}]});const tools=[
    {name:'langkah_read_progress',title:'Baca hasil belajar Langkah',description:'Membaca ringkasan hasil belajar pada browser ini.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input===null||(input!==undefined&&(typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)))throw Error('Tidak menerima parameter.');return toolResult({completed:Object.keys(state.completed).length,total:123,due:K.due(state),next:nextLesson().id,xp:K.xp(state)});}},
    {name:'langkah_open_lesson',title:'Buka pelajaran Langkah',description:'Membuka penjelasan pelajaran yang dipilih. Tidak menyelesaikan soal atau memberikan poin.',inputSchema:{type:'object',properties:{lesson_id:{type:'string',description:'ID pelajaran f01–f08 atau g001–g115'}},required:['lesson_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||typeof input.lesson_id!=='string'||!lessons.has(input.lesson_id))throw Error('ID pelajaran tidak valid.');go('lesson/'+input.lesson_id);return toolResult({opened:input.lesson_id,title:lessons.get(input.lesson_id).title});}}
  ];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch(e){/* Browser eksperimental: UI tetap berfungsi. */}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
  render();registerModelTools();
})();

